import { Diagram, type DiagramModel, type DiagramNodeActivateDetail } from '@absoluteui/components/diagram';

const model: DiagramModel = {
  nodes: [
    { id: 'start', label: 'Request submitted', shape: 'ellipse' },
    { id: 'manager', label: 'Manager approval', shape: 'diamond', height: 96 },
    { id: 'done', label: 'Approved', shape: 'rounded' },
    { id: 'rejected', label: 'Rejected', shape: 'rounded' },
  ],
  edges: [
    { id: 'e1', from: 'start', to: 'manager' },
    { id: 'e2', from: 'manager', to: 'done', label: 'Yes' },
    { id: 'e3', from: 'manager', to: 'rejected', label: 'No', dashed: true },
  ],
};

const host = document.createElement('div');
document.body.append(host);
Diagram.create(host, { label: 'Leave approval', model, layout: { algorithm: 'layered', direction: 'TB' } });
host.addEventListener('aui-node-activate', (event) => {
  host.dataset.opened = (event as CustomEvent<DiagramNodeActivateDetail>).detail.node.label;
});

import { Diagram, type DiagramChangeDetail, type DiagramModel } from '@absoluteui/components/diagram';
import { Button } from '@absoluteui/components/button';

let saved: DiagramModel = {
  nodes: [
    { id: 'a', label: 'Draft', x: 0, y: 0 },
    { id: 'b', label: 'Review', x: 240, y: 0, locked: true },
  ],
  edges: [{ id: 'ab', from: 'a', to: 'b' }],
};

const host = document.createElement('div');
document.body.append(host);
const diagram = Diagram.create(host, {
  label: 'Document workflow',
  model: saved,
  editable: true,
  routing: 'curved',
  // Nothing may lead back to the draft.
  canConnect: (_from, to) => to.id !== 'a',
});
host.addEventListener('aui-change', (event) => {
  saved = (event as CustomEvent<DiagramChangeDetail>).detail.model;
});
const undo = document.createElement('button');
undo.type = 'button';
undo.textContent = 'Undo';
Button.enhance(undo);
undo.addEventListener('click', () => {
  diagram.undo();
});
host.after(undo);

