import { Diagram, downloadDiagram } from '@absoluteui/components/diagram';
import { Button } from '@absoluteui/components/button';

const SVG = 'http://www.w3.org/2000/svg';
const host = document.createElement('div');
document.body.append(host);
const diagram = Diagram.create(host, {
  label: 'Escalation',
  model: {
    nodes: [
      { id: 'alert', label: 'Alert', shape: 'custom', x: 0, y: 0, width: 120, height: 72 },
      { id: 'oncall', label: 'On-call engineer', x: 220, y: 4 },
    ],
    edges: [{ id: 'page', from: 'alert', to: 'oncall', label: 'Page' }],
  },
  // Non-interactive SVG in local coordinates; the label is drawn on top.
  renderShape: (_node, { width, height, doc }) => {
    const hexagon = doc.createElementNS(SVG, 'path');
    hexagon.setAttribute('d', `M20 0H${String(width - 20)}L${String(width)} ${String(height / 2)}L${String(width - 20)} ${String(height)}H20L0 ${String(height / 2)}Z`);
    hexagon.setAttribute('class', 'escalation-shape');
    return hexagon;
  },
});
const save = document.createElement('button');
save.type = 'button';
save.textContent = 'Download SVG';
Button.enhance(save);
save.addEventListener('click', () => {
  void downloadDiagram(diagram, { format: 'svg', fileName: 'escalation' });
});
host.after(save);

import { layoutDiagram } from '@absoluteui/components/diagram';

const result = layoutDiagram(
  [
    { id: 'a', width: 120, height: 48 },
    { id: 'b', width: 120, height: 48 },
    { id: 'c', width: 120, height: 48 },
  ],
  [{ from: 'a', to: 'b' }, { from: 'a', to: 'c' }],
  { algorithm: 'tree', direction: 'LR', nodeGap: 24, rankGap: 48 },
);
const b = result.positions.get('b');
document.body.dataset.size = `${String(result.width)}x${String(result.height)}, b at ${String(b?.x ?? 0)}`;
